message BaoSettleItem {
    int32 from_seat = 1;  // 承包方座位（赔付方）
    int32 to_seat   = 2;  // 被承包方座位（触发承包关系的另一方）
    int64 score     = 3;  // 承包结算分数
    int32 relation  = 4;  // 承包关系（0=无 / 1=承包 / 2=倒承包，与 TanItem.bao_relation 同枚举）
}
